func TestMain(m *testing.M) {
	log.SetOutput(io.Discard)
	// A footer message carries a three-second expiry, and reading a Cmd runs it.
	sharedcomponents.FooterMsgDuration = time.Millisecond

	code := m.Run()

	log.SetOutput(os.Stderr)
	os.Exit(code)
}

