func (m Model) syncStart(entry template.Entry) tea.Cmd {
	job := syncJob{
		entry: entry,
		creds: template.CredentialsFor(m.config, m.secrets, entry.Source),
		cache: m.cache,
	}
	run := jobs.NewRun(jobs.KindSync, command.ViewTemplates, "", entry.Name, entry.Slug).WithDisplay(entry.Slug, entry.Name)
	return jobs.Start(run, syncTemplateCmd(job))
}

// handleSyncComplete says how the sync ended.
func (m Model) handleSyncComplete(msg SyncCompleteMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		return m, m.footer.Error("Sync of " + msg.Name + " failed — check logs")
	}
	return m, tea.Batch(m.refreshSynced(), m.footer.Info("Synced "+msg.Name+" — "+sharedcomponents.Plural(msg.Files, "file", "files")))
}
// reads at render (no row is rebuilt), and the footer spinner.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.table.SetBlinkPhase(msg.Blink)
	m.footer.SetSpinnerFrame(msg.RenderedFrame)
	return m, nil
}

// handleScanComplete says how the scan ended. The counts are in the footer and
// the report is in `:sec`, where this directory is listed like any other scanned
// target.
func (m Model) handleScanComplete(msg ScanCompleteMsg) (tea.Model, tea.Cmd) {
	// A scan reads the template through the cache, which may have made the copy.
	refresh := m.refreshSynced()
	var cmd tea.Cmd
	switch {
	case msg.Err != nil:
		cmd = m.footer.Error("Scan of " + msg.Name + " failed — check logs")
	case msg.Partial:
		cmd = m.footer.Warn("Scanned " + msg.Name + ", but a scan stage failed — check logs")
	default:
		cmd = m.footer.Info(scanSummary(msg))
	}
	return m, tea.Batch(refresh, cmd)
}

